using SimplePZMapmaker.Core;
namespace SimplePZMapmaker.Web.Services;
public static partial class AssetRules
{
 public static void Building(Building b,GameAssetCatalog assets,bool requireAccess=true){BuildingDesigner.Validate(b,requireAccess);if(b.Design is null){StampDependencies(b,assets);return;}var d=b.Design;
  void Floor(string id){var a=assets.Get(id);if(!a.Floor||a.Properties.ContainsKey("water"))throw new ArgumentException("An indoor tile must have a complete dry floor surface.");}
  if(d.Style.Length>0){var s=VisualStyles.All[d.Style];Floor(s.Floor);Floor(s.WetFloor);foreach(var direction in new[]{"n","w"})foreach(var kind in new[]{"wall","door","window"})CheckEdge(assets,WallCatalog.Tile(s.Wall,s.WallBase,kind,direction=="n"),null,direction,kind);}
  if(d.RoofTileset is not null)foreach(var i in Enumerable.Range(0,30).Where(i=>i%8<6))if(assets.Get(d.RoofTileset+"_"+i).Category!="roofs")throw new ArgumentException("A complete 30-degree roof tileset is required.");
  if(d.FlatRoofTile is not null)Floor(d.FlatRoofTile);
  foreach(var f in d.Floors){if(f.FloorTile is not null)Floor(f.FloorTile);foreach(var id in f.FloorTiles.Values)Floor(id);foreach(var e in f.Edges){if(e.WallTile is not null||e.OpeningTile is not null)CheckEdge(assets,e.WallTile,e.OpeningTile,e.Edge,e.Kind);if(e.OverlayTile is not null)CheckOverlay(assets,e.OverlayTile,e.Edge);}foreach(var o in f.Objects.Where(o=>o.Kind=="asset"))CheckParts(assets,o.Asset!,o.Parts);}StampDependencies(b,assets);
 }
 public static void Project(MapProject p,GameAssetCatalog assets){ValidateProjectStructure(p);foreach(var b in p.Buildings.Concat(p.BuildingLibrary))Building(b,assets);StampDependencies(p,assets);ProjectValidator.Validate(p);foreach(var d in p.Decorations)CheckParts(assets,d.Asset,d.Parts);foreach(var (i,id) in p.SurfaceTiles){var a=assets.Get(id);if(!a.Floor||a.Properties.ContainsKey("water")!=(p.Terrain[i]==Terrain.Water))throw new ArgumentException("The selected surface type does not match the tile: "+id);}}
 public static void CheckParts(GameAssetCatalog assets,string id,List<BuildingObjects.Part> parts){var actual=assets.PlacementFor(id);var expected=actual.Parts.OrderBy(p=>p.Dy).ThenBy(p=>p.Dx).Select(p=>(p.Dx,p.Dy,p.Tile,p.Flags));if(!parts.OrderBy(p=>p.Dy).ThenBy(p=>p.Dx).Select(p=>(p.Dx,p.Dy,p.Tile,p.Flags)).SequenceEqual(expected))throw new ArgumentException("The tile group or physical properties do not match the game resource.");}
 public static void CheckOverlay(GameAssetCatalog assets,string overlay,string direction){var p=assets.Get(overlay).Properties;if(p.ContainsKey("WallOverlay")&&(p.ContainsKey("attachedN")&&direction!="n"||p.ContainsKey("attachedW")&&direction!="w"))throw new ArgumentException("The wall decoration faces the other direction.");}
 public static void CheckEdge(GameAssetCatalog assets,string? wall,string? opening,string direction,string kind){var suffix=direction=="n"?"N":"W";if(wall is not null){var p=assets.Get(wall).Properties;var needed=kind=="door"?"DoorWall"+suffix:kind=="window"?"Window"+suffix:"Wall"+suffix;if(!p.ContainsKey(needed)&&!(kind=="window"&&p.ContainsKey("WindowWall"+suffix)))throw new ArgumentException("The wall tile does not match the direction or opening type.");}if(opening is not null&&(kind is not("door" or "window")||!assets.Get(opening).Properties.ContainsKey((kind=="door"?"door":"window")+suffix)))throw new ArgumentException("The door or window does not match the selected edge.");}
}
